//! Rendering the manifest as `abaigram.yaml`.

use serde_json::{Map, Value};

use super::Manifest;

/// Render the manifest as YAML text with exactly one trailing newline.
pub fn render_yaml(manifest: &Manifest) -> String {
    let value = serde_json::to_value(manifest).expect("a manifest serializes");
    let Value::Object(root) = value else {
        unreachable!("a manifest serializes to an object");
    };
    let entry = &manifest.entry;
    let mut out = format!(
        "# abaigram.yaml: the manifest of {name} as an abaigram (abaigrammar {v}).\n\
         # Generated by `{entry} manifest` from the program's declarations in code.\n\
         # Do not edit by hand: `{entry} doctor` checks that this file agrees with the code.\n\
         # Regenerate with `{entry} manifest > abaigram.yaml`.\n\n",
        name = manifest.name,
        v = manifest.abaigrammar,
    );
    write_entries(&mut out, &root, 0);
    out
}

fn pad(out: &mut String, indent: usize) {
    for _ in 0..indent {
        out.push(' ');
    }
}

fn write_entries(out: &mut String, map: &Map<String, Value>, indent: usize) {
    for (key, value) in map {
        pad(out, indent);
        write_entry(out, key, value, indent);
    }
}

fn write_entry(out: &mut String, key: &str, value: &Value, indent: usize) {
    out.push_str(&string_scalar(key));
    out.push(':');
    write_after_key(out, value, indent);
}

fn write_after_key(out: &mut String, value: &Value, indent: usize) {
    match value {
        Value::Object(map) if !map.is_empty() => {
            out.push('\n');
            write_entries(out, map, indent + 2);
        }
        Value::Array(list) if !list.is_empty() => {
            out.push('\n');
            write_seq(out, list, indent + 2);
        }
        _ => {
            out.push(' ');
            out.push_str(&inline(value));
            out.push('\n');
        }
    }
}

fn write_seq(out: &mut String, list: &[Value], indent: usize) {
    for item in list {
        pad(out, indent);
        out.push('-');
        match item {
            Value::Object(map) if !map.is_empty() => {
                out.push(' ');
                let mut entries = map.iter();
                if let Some((key, value)) = entries.next() {
                    write_entry(out, key, value, indent + 2);
                }
                for (key, value) in entries {
                    pad(out, indent + 2);
                    write_entry(out, key, value, indent + 2);
                }
            }
            Value::Array(inner) if !inner.is_empty() => {
                out.push('\n');
                write_seq(out, inner, indent + 2);
            }
            _ => {
                out.push(' ');
                out.push_str(&inline(item));
                out.push('\n');
            }
        }
    }
}

/// A scalar, an empty map or an empty list, written on one line.
fn inline(value: &Value) -> String {
    match value {
        Value::Null => "null".to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => number(&n.to_string()),
        Value::String(s) => string_scalar(s),
        Value::Object(_) => "{}".to_string(),
        Value::Array(_) => "[]".to_string(),
    }
}

/// A number as a YAML 1.1 reader takes it: an exponent form gets a dot in
/// its mantissa and a sign on its exponent, so `1e21` becomes `1.0e+21`.
fn number(text: &str) -> String {
    let Some(at) = text.find(['e', 'E']) else {
        return text.to_string();
    };
    let (mantissa, rest) = text.split_at(at);
    let (mark, exponent) = rest.split_at(1);
    let dot = if mantissa.contains('.') { "" } else { ".0" };
    let sign = if exponent.starts_with(['+', '-']) {
        ""
    } else {
        "+"
    };
    format!("{mantissa}{dot}{mark}{sign}{exponent}")
}

pub(crate) fn string_scalar(value: &str) -> String {
    if is_plain(value) {
        value.to_string()
    } else {
        quote(value)
    }
}

fn is_plain(value: &str) -> bool {
    let Some(first) = value.chars().next() else {
        return false;
    };
    let allowed = |c: char| {
        c.is_ascii_alphanumeric()
            || matches!(
                c,
                ' ' | '_' | '.' | '/' | '(' | ')' | '~' | '+' | '=' | ',' | '-'
            )
    };
    if !value.chars().all(allowed) {
        return false;
    }
    let good_start = first.is_ascii_alphabetic()
        || first == '/'
        || first == '_'
        || value.starts_with("~/")
        || value.starts_with("./");
    if !good_start || value.ends_with(' ') {
        return false;
    }
    let lower = value.to_ascii_lowercase();
    !matches!(
        lower.as_str(),
        "true" | "false" | "null" | "yes" | "no" | "on" | "off" | "y" | "n"
    )
}

fn quote(value: &str) -> String {
    let mut out = String::with_capacity(value.len() + 2);
    out.push('"');
    for c in value.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            c if c < '\u{20}'
                || c == '\u{7F}'
                || ('\u{80}'..='\u{9F}').contains(&c)
                || c == '\u{2028}'
                || c == '\u{2029}'
                || c == '\u{FEFF}'
                || c == '\u{FFFE}'
                || c == '\u{FFFF}' =>
            {
                out.push_str(&format!("\\u{:04X}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::manifest::testdata::sample;
    use serde_json::json;

    const GOLDEN: &str = r#"# abaigram.yaml: the manifest of jobs as an abaigram (abaigrammar 0.1).
# Generated by `./bin/jobs abai manifest` from the program's declarations in code.
# Do not edit by hand: `./bin/jobs abai doctor` checks that this file agrees with the code.
# Regenerate with `./bin/jobs abai manifest > abaigram.yaml`.

abaigrammar: "0.1"
name: jobs
entry: ./bin/jobs abai
modes:
  - sidecar
  - turns
check:
  run: make bench
content:
  identity: abai/identity.md
  use: abai/use.md
audit:
  path: ~/.abai/audit/jobs.jsonl
lifecycle:
  pause: cooperative
  stop:
    graceful: "10s"
    handler: stop
attention:
  budget:
    wakes_per_minute: 30
    tokens_per_hour: 200000
policy:
  confirm_timeout: "60s"
deviations:
  - A first deviation (section 6.3).
cells:
  - name: queue.depth
    type: int
    access: read
    doc: Number of jobs waiting. Rises when producers outpace workers.
  - name: worker.count
    type: int
    access: readwrite
    doc: Active worker threads. The pool resizes within a second of a change.
    range:
      - 1
      - 64
    default: 4
    cadence: 1000
    policy: auto
events:
  - name: job.failed
    doc: A job exhausted its retries.
    payload:
      job_id:
        type: string
        max: 64
      error:
        type: string
        max: 512
    wakes: always
capabilities:
  - name: job.retry
    doc: Requeue a failed job once.
    params:
      job_id: string
    result:
      ok: bool
    effect: mutate
    dispatch: safepoint
    timeout: "5s"
    policy: confirm
    example:
      job_id: job-0001
decisions:
  - name: on_backlog
    doc: Asked when the queue depth crosses the high-water mark.
    context:
      depth: int
      workers: int
    options:
      - scale_up
      - shed_oldest
      - wait
    default: wait
    timeout: "5s"
    policy: auto
turns:
  - name: end_of_batch
    doc: After each batch completes. The agent may tune worker.count.
    timeout: "30s"
"#;

    fn scalar(s: &str) -> String {
        inline(&Value::String(s.to_string()))
    }

    fn body(value: Value) -> String {
        let Value::Object(map) = value else {
            panic!("an object");
        };
        let mut out = String::new();
        write_entries(&mut out, &map, 0);
        out
    }

    #[test]
    fn the_sample_renders() {
        assert_eq!(render_yaml(&sample()), GOLDEN);
    }

    #[test]
    fn plain_strings() {
        for s in [
            "jobs", "~/x", "./x", "/a/b", "_x", "job-0001", "a b", "x=1,y+2",
        ] {
            assert_eq!(scalar(s), s, "{s}");
        }
    }

    #[test]
    fn quoted_strings() {
        let cases = [
            ("yes", r#""yes""#),
            ("No", r#""No""#),
            ("0.1", r#""0.1""#),
            ("30s", r#""30s""#),
            ("", r#""""#),
            (" a", r#"" a""#),
            ("a ", r#""a ""#),
            ("a: b", r#""a: b""#),
            ("a #b", r#""a #b""#),
            ("- a", r#""- a""#),
            ("~", r#""~""#),
            (".5", r#"".5""#),
            ("a\"b", r#""a\"b""#),
            ("a\\b", r#""a\\b""#),
            ("a\nb", r#""a\nb""#),
            ("a\tb\r", r#""a\tb\r""#),
            ("héllo", "\"héllo\""),
            ("a\u{2028}b", r#""a\u2028b""#),
            (
                "a\u{1}\u{7F}\u{85}\u{FEFF}",
                r#""a\u0001\u007F\u0085\uFEFF""#,
            ),
        ];
        for (s, want) in cases {
            assert_eq!(scalar(s), want, "{s:?}");
        }
    }

    #[test]
    fn other_scalars() {
        assert_eq!(inline(&json!(null)), "null");
        assert_eq!(inline(&json!(true)), "true");
        assert_eq!(inline(&json!(1.5)), "1.5");
        assert_eq!(inline(&json!(-3)), "-3");
    }

    #[test]
    fn exponents_read_as_floats() {
        assert_eq!(number("1e21"), "1.0e+21");
        assert_eq!(number("1e-6"), "1.0e-6");
        assert_eq!(number("1.5e300"), "1.5e+300");
        assert_eq!(number("2E+5"), "2.0E+5");
        assert_eq!(number("-3"), "-3");
        assert_eq!(number("0.25"), "0.25");
        assert_eq!(inline(&json!(1e21)), "1.0e+21");
        assert_eq!(inline(&json!(1.5e300)), "1.5e+300");
    }

    #[test]
    fn noncharacters_are_escaped() {
        assert_eq!(scalar("a\u{FFFE}\u{FFFF}"), r#""a\uFFFE\uFFFF""#);
    }

    #[test]
    fn empty_collections_render_inline() {
        assert_eq!(
            body(json!({"cells": [], "model": {}, "list": [[], {}]})),
            "cells: []\nmodel: {}\nlist:\n  - []\n  - {}\n"
        );
    }

    #[test]
    fn a_list_of_lists() {
        assert_eq!(
            body(json!({"a": [[1, 2], [[3]]]})),
            "a:\n  -\n    - 1\n    - 2\n  -\n    -\n      - 3\n"
        );
    }

    #[test]
    fn a_map_in_a_list_whose_first_value_is_a_map() {
        assert_eq!(
            body(json!({"a": [{"m": {"x": 1, "k": [2]}, "z": "w"}]})),
            "a:\n  - m:\n      x: 1\n      k:\n        - 2\n    z: w\n"
        );
    }

    #[test]
    fn one_trailing_newline_and_no_trailing_spaces() {
        let text = render_yaml(&sample());
        assert!(text.ends_with('\n'));
        assert!(!text.ends_with("\n\n"));
        for line in text.lines() {
            assert!(!line.ends_with(' '), "{line:?}");
        }
    }
}
